static void pump(DWORD ms){ULONGLONG start=GetTickCount64();do{MSG m;while(PeekMessageW(&m,NULL,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}Sleep(1);}while(GetTickCount64()-start<ms);}
static ui_status_t present(ui_component_t *c,const char *id,ui_element_presentation_t *p){ULONGLONG start=GetTickCount64();ui_status_t s;do{s=ui_component_get_presentation(c,id,p);if(s!=UI_STATUS_PENDING){if(s!=UI_STATUS_OK||!p->visible)printf("presentation %s status=%d visible=%d rect=%d,%d,%d,%d clip=%d,%d,%d,%d\n",id,s,p->visible,p->rect.x,p->rect.y,p->rect.width,p->rect.height,p->clip.x,p->clip.y,p->clip.width,p->clip.height);return s;}pump(1);}while(GetTickCount64()-start<10000);return s;}
static void input(ui_component_t *c,ui_input_kind_t kind,int x,int y,unsigned key){ui_input_event_t e={0};e.size=sizeof(e);e.kind=kind;e.x=x;e.y=y;e.key_code=key;e.pointer_button=1;CHECK(ui_component_dispatch_input(c,&e)==UI_STATUS_OK);if(runtime_mode)pump(80);}
