static void source(ui_component_t *c,const ui_component_query_t *q,void *user){ui_row_t rows[128]={0};ui_cell_t (*cells)[64];ui_component_batch_t b={0};size_t n=q->count;if(q->kind!=UI_QUERY_ROWS)return;late=*q;late.sort_column=NULL;if(delayed)return;cells=calloc(128,sizeof(*cells));CHECK(cells!=NULL);if(!cells)return;if(n>128)n=128;if(q->first>=total)n=0;else if(n>total-q->first)n=(size_t)(total-q->first);
    for(size_t i=0;i<n;++i){rows[i].size=sizeof(rows[i]);rows[i].id=q->parent_id?1000000+q->first+i+1:q->first+i+1;rows[i].parent_id=q->parent_id;rows[i].has_children=q->parent_id?0:1;rows[i].title="stable row";rows[i].cells=cells[i];rows[i].cell_count=user?64:0;for(size_t j=0;user&&j<64;++j){cells[i][j].size=sizeof(ui_cell_t);cells[i][j].column_id=((ui_column_desc_t *)user)[j].id;cells[i][j].kind=UI_VALUE_TEXT;cells[i][j].text="value";}}
    b.size=sizeof(b);b.component_generation=q->component_generation;b.request_id=q->request_id;b.first=q->first;b.parent_id=q->parent_id;b.total_count=total;b.rows=rows;b.row_count=n;CHECK(ui_component_submit(c,&b)==UI_STATUS_OK);free(cells);}
